104	// A major command line at column 0: `name   brief`.
105	void print_major(std::FILE* out, const char* name, const char* brief) {
106	  std::fprintf(out, "%-7s %s\n", name, brief);
107	}
108	
109	// A subcommand/target line, indented two under its command: `  name   brief`.
110	void print_sub(std::FILE* out, const char* name, const char* brief) {
111	  std::fprintf(out, "  %-9s %s\n", name, brief);
112	}
113	
114	// An option line: `<indent>--flag    [TAG  ]brief`, flags aligned to a column.
115	void print_opt(std::FILE* out, const OptRow& o) {
116	  if (o.tag[0])
117	    std::fprintf(out, "%-29s %s  %s\n", o.flag, o.tag, o.brief);
118	  else
119	    std::fprintf(out, "%-29s %s\n", o.flag, o.brief);
120	}
121	
122	// `run`: major line, the mode subcommands, then the option list (dev options
123	// only under ANDESIM_DEV). Shared by the top-level tree and `run --help`.
124	void print_run_block(std::FILE* out) {
125	  print_major(out, "run", "run one simulation");
126	  for (const ModeRow& m : kRunModes) print_sub(out, m.name, m.brief);
127	  std::fputs("\n", out);
128	  for (const OptRow& o : kRunOpts) {
129	    if (o.dev && !is_dev_mode()) continue;
130	    print_opt(out, o);
131	  }
132	}
133	
134	void print_list_block(std::FILE* out) {
135	  print_major(out, "list", "list what is available");
136	  for (const TargetRow& t : kListTargets) {
137	    if (t.dev && !is_dev_mode()) continue;
138	    print_sub(out, t.name, t.brief);
139	  }
140	}
141	
142	void print_doctor_block(std::FILE* out) {
143	  print_major(out, "doctor", "check toolchain + fixtures are present");
144	}
