146	// Top-level `andesim --help`: the whole tree -- every major command, its
147	// subcommands, and run's full option list, so one screen shows everything.
148	void print_usage(std::FILE* out) {
149	  std::fputs("usage: andesim <command> [options] <ELF> [-- <engine args>]\n\n",
150	             out);
151	  std::fputs("Multi-engine driver for the Andes simulators (QEMU + vsim).\n\n",
152	             out);
153	  print_run_block(out);
154	  std::fputs("\n", out);
155	  print_list_block(out);
156	  std::fputs("\n", out);
157	  print_doctor_block(out);
158	  std::fputs(
159	      "\n'andesim run --help' / 'andesim list --help' for per-command "
160	      "detail.\n",
161	      out);
162	}
